package com.example.fluxxloop

// Automatisch aus den colorpalette_*.xml der Original-APK erzeugt.

class Gradient(val colors: IntArray, val points: FloatArray)

class LoopPalette(
    val name: String,
    val home: Gradient?,
    val lock: Gradient?,
    val batteryLow: Gradient?,
    val charging: Gradient?,
    /** Loop-Farbgruppen: Normal / Battery low / Charging / Battery empty */
    val normal: List<IntArray>?,
    val low: List<IntArray>?,
    val chargingLoops: List<IntArray>?,
    val empty: List<IntArray>?,
)

